const MAXIMO = 10;
const estado = { fome: 4, energia: 6 };

const gato = document.querySelector("#gato");
const botaoBrincar = document.querySelector("#brincar");

function humor() {
  if (estado.fome >= 8) {
    return "Estou com fome!";
  }
  if (estado.energia < 3) {
    return "Estou cansado...";
  }
  return "Estou feliz!";
}

function desenhar() {
  document.querySelector("#fome").textContent = estado.fome;
  document.querySelector("#energia").textContent = estado.energia;
  document.querySelector("#barra-fome").style.width = estado.fome * 10 + "%";
  document.querySelector("#barra-energia").style.width = estado.energia * 10 + "%";

  const frase = humor();
  document.querySelector("#humor").textContent = frase;
  gato.classList.toggle("triste", frase !== "Estou feliz!");
  botaoBrincar.disabled = estado.energia < 2;
}

document.querySelector("#alimentar").addEventListener("click", () => {
  estado.fome = Math.max(0, estado.fome - 3);
  desenhar();
});

botaoBrincar.addEventListener("click", () => {
  estado.energia = Math.max(0, estado.energia - 2);
  estado.fome = Math.min(MAXIMO, estado.fome + 1);
  desenhar();
});

document.querySelector("#dormir").addEventListener("click", () => {
  estado.energia = MAXIMO;
  estado.fome = Math.min(MAXIMO, estado.fome + 2);
  desenhar();
});

desenhar();

