const LADO = 5;
const TESOURO = { x: 3, y: 2 };
const estado = { x: 0, y: 0, passos: 0, achou: false };

// Cria as 25 casas do mapa: a casa da coluna x e da linha y é a de índice y * LADO + x
const mapa = document.querySelector("#mapa");
const casas = [];
for (let i = 0; i < LADO * LADO; i++) {
  const casa = document.createElement("div");
  casa.classList.add("casa");
  mapa.append(casa);
  casas.push(casa);
}

function desenhar() {
  casas.forEach((casa, i) => {
    casa.classList.toggle("heroi", i === estado.y * LADO + estado.x);
    casa.classList.toggle("tesouro", i === TESOURO.y * LADO + TESOURO.x);
  });
  document.querySelector("#passos").textContent = estado.passos;
  if (estado.achou) {
    document.querySelector("#mensagem").textContent = `Você achou o tesouro em ${estado.passos} passos!`;
  }
}

function mover(dx, dy) {
  if (estado.achou) {
    return;
  }
  const x = estado.x + dx;
  const y = estado.y + dy;
  if (x < 0 || x >= LADO || y < 0 || y >= LADO) {
    return;
  }
  estado.x = x;
  estado.y = y;
  estado.passos++;
  estado.achou = x === TESOURO.x && y === TESOURO.y;
  desenhar();
}

const DIRECOES = {
  ArrowUp: [0, -1],
  ArrowDown: [0, 1],
  ArrowLeft: [-1, 0],
  ArrowRight: [1, 0],
  w: [0, -1],
  s: [0, 1],
  a: [-1, 0],
  d: [1, 0],
};

document.addEventListener("keydown", (evento) => {
  const direcao = DIRECOES[evento.key];
  if (!direcao) {
    return;
  }
  evento.preventDefault();
  mover(direcao[0], direcao[1]);
});

document.querySelector("#cima").addEventListener("click", () => mover(0, -1));
document.querySelector("#baixo").addEventListener("click", () => mover(0, 1));
document.querySelector("#esquerda").addEventListener("click", () => mover(-1, 0));
document.querySelector("#direita").addEventListener("click", () => mover(1, 0));

desenhar();

