    const j = Math.floor(Math.random() * (i + 1));
    [lista[i], lista[j]] = [lista[j], lista[i]];
  }
  return lista;
}

const tabuleiro = document.querySelector("#tabuleiro");

let estado;
let espera = null;

function novoJogo() {
  clearTimeout(espera);
  const simbolos = embaralhar([...SIMBOLOS, ...SIMBOLOS]);
  estado = {
    cartas: simbolos.map((simbolo) => ({ simbolo, virada: false, achada: false })),
    abertas: [],
    jogadas: 0,
    pares: 0,
    travado: false,
  };

  tabuleiro.textContent = "";
