    const botao = document.createElement("button");
    botao.classList.add("carta");
    botao.dataset.simbolo = carta.simbolo;
    botao.addEventListener("click", () => virar(i));
    tabuleiro.append(botao);
  });
  desenhar();
}

function desenhar() {
  const botoes = tabuleiro.querySelectorAll(".carta");
