    botoes[i].classList.toggle("virada", carta.virada);
    botoes[i].classList.toggle("achada", carta.achada);
  });
  document.querySelector("#jogadas").textContent = estado.jogadas;
  document.querySelector("#pares").textContent = estado.pares;
  document.querySelector("#mensagem").textContent =
    estado.pares === SIMBOLOS.length ? `Você venceu em ${estado.jogadas} jogadas!` : "";
}

function virar(i) {
  const carta = estado.cartas[i];
  if (estado.travado || carta.virada || carta.achada) {
    return;
  }

  carta.virada = true;
  estado.abertas.push(carta);

  if (estado.abertas.length === 2) {
    estado.jogadas++;
    const [a, b] = estado.abertas;
    estado.abertas = [];
    if (a.simbolo === b.simbolo) {
      a.virada = false;
      b.virada = false;
      a.achada = true;
      b.achada = true;
      estado.pares++;
    } else {
      estado.travado = true;
      espera = setTimeout(() => {
        a.virada = false;
        b.virada = false;
        estado.travado = false;
        desenhar();
      }, 1000);
    }
  }
  desenhar();
}

document.querySelector("#reiniciar").addEventListener("click", novoJogo);

novoJogo();
